import { createError } from "../composables/error.js";
const intervalError = "[nuxt] `setInterval` should not be used on the server. Consider wrapping it with an `onNuxtReady`, `onBeforeMount` or `onMounted` lifecycle hook, or ensure you only call it in the browser by checking `import.meta.client`.";
export const setInterval = import.meta.client ? globalThis.setInterval : (() => {
  if (import.meta.dev) {
    throw createError({
      status: 500,
      message: intervalError
    });
  }
  console.error(intervalError);
});
/**
 * stores/runtime.ts
 * ─────────────────────────────────────────────────────────────────────────────
 * Pinia store for the viewer runtime state.
 * Tracks active tour, active scene, navigation history, and loading state.
 * ─────────────────────────────────────────────────────────────────────────────
 */
import { defineStore } from 'pinia';
import type { TourConfig, TourScene } from '~/types/tour';

// ── Inline navigation state (previously in core/runtime/navigation.ts) ────────

interface SceneRef { tourId: string; sceneId: string }

interface NavigationState {
  entryTourId: string;
  current: SceneRef;
  history: SceneRef[];
}

function createNavigationState(tourId: string, sceneId: string): NavigationState {
  return { entryTourId: tourId, current: { tourId, sceneId }, history: [] };
}

function navTo(state: NavigationState, dest: SceneRef): NavigationState {
  return {
    ...state,
    current: dest,
    history: state.history.length < 50
      ? [...state.history, state.current]
      : [...state.history.slice(1), state.current],
  };
}

function navBack(state: NavigationState): NavigationState {
  if (!state.history.length) return state;
  const prev = state.history[state.history.length - 1]!;
  return { ...state, current: prev, history: state.history.slice(0, -1) };
}

function canGoBackFn(state: NavigationState): boolean {
  return state.history.length > 0;
}

function isInGuestTourFn(state: NavigationState): boolean {
  return state.current.tourId !== state.entryTourId;
}

// ── Inline scene resolvers (previously in core/runtime/resolver.ts) ───────────

function resolveScene(tour: TourConfig, sceneId: string): TourScene | undefined {
  return tour.scenes.find((s) => s.id === sceneId);
}

function resolveInitialScene(tour: TourConfig, preferredId?: string): TourScene {
  if (preferredId) {
    const found = tour.scenes.find((s) => s.id === preferredId);
    if (found) return found;
  }
  const initial = tour.initialSceneId
    ? tour.scenes.find((s) => s.id === tour.initialSceneId)
    : undefined;
  return initial ?? tour.scenes[0]!;
}

// ── Store ─────────────────────────────────────────────────────────────────────

export const useRuntimeStore = defineStore('runtime', () => {
  // ── State ─────────────────────────────────────────────────────────────────

  /** Currently loaded tour data (scenes only — no WebGL refs) */
  const tour    = ref<TourConfig | null>(null);
  const loading = ref(false);
  const error   = ref<string | null>(null);

  /** Navigation stack */
  const navState = ref<NavigationState | null>(null);

  // ── Computed ──────────────────────────────────────────────────────────────

  const activeScene = computed<TourScene | undefined>(() => {
    if (!tour.value || !navState.value) return undefined;
    if (navState.value.current.tourId === tour.value.slug) {
      return resolveScene(tour.value, navState.value.current.sceneId);
    }
    return undefined;
  });

  const activeSceneId  = computed(() => navState.value?.current.sceneId ?? '');
  const activeTourId   = computed(() => navState.value?.current.tourId ?? '');
  const entryTourId    = computed(() => navState.value?.entryTourId ?? '');
  const canGoBack      = computed(() => navState.value ? canGoBackFn(navState.value) : false);
  const inGuestTour    = computed(() => navState.value ? isInGuestTourFn(navState.value) : false);
  const scenes         = computed<TourScene[]>(() => tour.value?.scenes ?? []);
  const sceneIndex     = computed(() => {
    if (!navState.value || !tour.value) return 0;
    return tour.value.scenes.findIndex((s) => s.id === activeSceneId.value) + 1;
  });

  // ── Actions ───────────────────────────────────────────────────────────────

  async function loadTour(tourId: string, preferredSceneId?: string): Promise<void> {
    if (loading.value) return;
    loading.value = true;
    error.value   = null;

    try {
      const res = await $fetch<{ item: TourConfig }>(`/api/tours/${tourId}`);
      if (!res.item) throw new Error('Tour không tồn tại.');

      tour.value = res.item;

      const initial = resolveInitialScene(res.item, preferredSceneId);
      navState.value = createNavigationState(tourId, initial.id);
    } catch (e: any) {
      error.value = e?.data?.statusMessage ?? e?.message ?? 'Lỗi tải tour.';
    } finally {
      loading.value = false;
    }
  }

  function navigateTo(sceneId: string, tourId?: string): void {
    if (!navState.value) return;
    navState.value = navTo(navState.value, {
      tourId:  tourId ?? tour.value?.slug ?? '',
      sceneId,
    });
  }

  function goBack(): void {
    if (!navState.value) return;
    navState.value = navBack(navState.value);
  }

  function reset(): void {
    tour.value     = null;
    navState.value = null;
    loading.value  = false;
    error.value    = null;
  }

  return {
    // State
    tour, loading, error, navState,
    // Computed
    activeScene, activeSceneId, activeTourId, entryTourId,
    canGoBack, inGuestTour, scenes, sceneIndex,
    // Actions
    loadTour, navigateTo, goBack, reset,
  };
});
/**
 * ─────────────────────────────────────────────────────────────────
 * Map2DStrategy — Canvas-based 2D floorplan map with multi-floor
 *
 * Renders:
 *   - Floor tabs at top
 *   - Floorplan background image
 *   - Connection lines between nodes
 *   - Node dots (current = amber, others = white)
 *   - Camera heading arrow on current node
 *   - Hover tooltips
 *   - Exit links (dashed lines to cross-floor nodes)
 * ─────────────────────────────────────────────────────────────────
 */

import type { Camera } from 'three';
import type { IMapStrategy, MapConfig, MapFloor, MapNode } from './IMapStrategy';

// ── Constants ────────────────────────────────────────────────────

const TAB_HEIGHT = 32;
const NODE_RADIUS = 6;
const NODE_RADIUS_CURRENT = 9;
const ARROW_LENGTH = 20;
const TOOLTIP_FONT = '600 11px "Be Vietnam Pro", sans-serif';
const TAB_FONT = '600 11px "Be Vietnam Pro", sans-serif';
const COLORS = {
  bg: '#14151f',
  tabBg: 'rgba(255,255,255,0.06)',
  tabActive: 'rgba(59,130,246,0.25)',
  tabBorder: 'rgba(59,130,246,0.6)',
  tabText: 'rgba(255,255,255,0.5)',
  tabTextActive: '#93c5fd',
  node: 'rgba(255,255,255,0.65)',
  nodeHover: '#fff',
  nodeCurrent: '#f59e0b',
  nodeCurrentBorder: '#fff',
  connection: 'rgba(255,255,255,0.18)',
  connectionExit: 'rgba(59,130,246,0.35)',
  arrow: 'rgba(245,158,11,0.85)',
  tooltipBg: 'rgba(10,10,20,0.88)',
  tooltipText: '#fff',
  tooltipBorder: 'rgba(255,255,255,0.15)',
};

export class Map2DStrategy implements IMapStrategy {
  private canvas!: HTMLCanvasElement;
  private ctx2d!: CanvasRenderingContext2D;
  private config!: MapConfig;
  private currentFloorId: string | null = null;
  private currentNodeId: string | null = null;
  private hoveredNodeId: string | null = null;
  private heading = { yaw: 0, pitch: 0, fov: 75 };
  private images = new Map<string, HTMLImageElement>();
  private dpr = 1;
  private displayW = 0;
  private displayH = 0;

  onNodeClick?: (nodeId: string) => void;
  onFloorChange?: (floorId: string) => void;

  // ── Init ──────────────────────────────────────────────────────

  async init(config: MapConfig, container: HTMLElement): Promise<void> {
    this.config = config;
    this.dpr = Math.min(window.devicePixelRatio, 2);

    this.canvas = document.createElement('canvas');
    this.canvas.style.cssText = 'width:100%;height:100%;display:block;cursor:default';
    this.ctx2d = this.canvas.getContext('2d')!;
    container.appendChild(this.canvas);

    // Set initial floor
    this.currentFloorId = config.defaultFloorId ?? config.floors[0]?.id ?? null;

    // Load all floor images in parallel
    await Promise.all(
      config.floors.map((floor) => this.loadImage(floor.id, floor.imageUrl)),
    );

    // Bind events
    this.canvas.addEventListener('click', this.handleClick);
    this.canvas.addEventListener('mousemove', this.handleMouseMove);
    this.canvas.addEventListener('mouseleave', this.handleMouseLeave);

    this.resize(container.clientWidth, container.clientHeight);
  }

  // ── API ───────────────────────────────────────────────────────

  update(_dt: number, _camera?: Camera): void {
    this.draw();
  }

  setCurrentNode(nodeId: string): void {
    this.currentNodeId = nodeId;
    // Auto-switch floor if needed
    if (this.config.autoSwitchFloor !== false) {
      const floor = this.findFloorForNode(nodeId);
      if (floor && floor.id !== this.currentFloorId) {
        this.currentFloorId = floor.id;
        this.onFloorChange?.(floor.id);
      }
    }
    this.draw();
  }

  setCameraHeading(yaw: number, pitch: number, fov?: number): void {
    this.heading = { yaw, pitch, fov: fov ?? 75 };
    this.draw();
  }

  setFloor(floorId: string): void {
    if (this.config.floors.some((f) => f.id === floorId)) {
      this.currentFloorId = floorId;
      this.draw();
    }
  }

  setVisible(visible: boolean): void {
    this.canvas.style.display = visible ? 'block' : 'none';
  }

  resize(width: number, height: number): void {
    this.displayW = width;
    this.displayH = height;
    this.canvas.width = width * this.dpr;
    this.canvas.height = height * this.dpr;
    this.draw();
  }

  dispose(): void {
    this.canvas.removeEventListener('click', this.handleClick);
    this.canvas.removeEventListener('mousemove', this.handleMouseMove);
    this.canvas.removeEventListener('mouseleave', this.handleMouseLeave);
    this.canvas.remove();
  }

  // ── Drawing ───────────────────────────────────────────────────

  private draw(): void {
    const ctx = this.ctx2d;
    const w = this.displayW;
    const h = this.displayH;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);

    // Background
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, w, h);

    const showTabs = this.config.showFloorTabs !== false && this.config.floors.length > 1;
    const tabH = showTabs ? TAB_HEIGHT : 0;
    const mapY = tabH;
    const mapH = h - tabH;

    // Floor tabs
    if (showTabs) this.drawTabs(ctx, w);

    // Current floor
    const floor = this.currentFloor();
    if (!floor) return;

    // Clip to map area
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, mapY, w, mapH);
    ctx.clip();

    // Floor image or grid pattern fallback
    const img = this.images.get(floor.id);
    const mapRect = this.contentRect(floor, w, mapH, mapY, img);
    if (img?.complete && img.naturalWidth > 0) {
      ctx.globalAlpha = 0.82;
      ctx.drawImage(img, mapRect.x, mapRect.y, mapRect.width, mapRect.height);
      ctx.globalAlpha = 1;
    } else {
      // No image → draw dot grid pattern
      this.drawGridPattern(ctx, w, mapH, mapY);
    }

    // Connections
    if (this.config.showConnections !== false) {
      this.drawConnections(ctx, floor, w, mapH, mapY);
    }

    // Nodes
    this.drawNodes(ctx, floor, w, mapH, mapY);

    // Camera arrow
    if (this.config.showCameraArrow !== false && this.currentNodeId) {
      this.drawCameraArrow(ctx, floor, w, mapH, mapY);
    }

    // Tooltip
    if (this.hoveredNodeId) {
      this.drawTooltip(ctx, floor, w, mapH, mapY);
    }

    ctx.restore();
  }

  private drawTabs(ctx: CanvasRenderingContext2D, w: number): void {
    const floors = this.config.floors;
    const tabW = w / floors.length;

    ctx.fillStyle = COLORS.tabBg;
    ctx.fillRect(0, 0, w, TAB_HEIGHT);

    // Bottom border
    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, TAB_HEIGHT);
    ctx.lineTo(w, TAB_HEIGHT);
    ctx.stroke();

    floors.forEach((floor, i) => {
      const x = i * tabW;
      const isActive = floor.id === this.currentFloorId;

      if (isActive) {
        ctx.fillStyle = COLORS.tabActive;
        ctx.fillRect(x, 0, tabW, TAB_HEIGHT);
        // Bottom highlight
        ctx.fillStyle = COLORS.tabBorder;
        ctx.fillRect(x, TAB_HEIGHT - 2.5, tabW, 2.5);
      }

      // Has current node indicator
      const hasCurrentNode = floor.nodes.some((n) => n.id === this.currentNodeId);

      ctx.font = TAB_FONT;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = isActive ? COLORS.tabTextActive : COLORS.tabText;
      const label = floor.shortName ?? floor.name;
      ctx.fillText(label, x + tabW / 2, TAB_HEIGHT / 2);

      // Dot indicator if current scene is on this floor (but tab isn't active)
      if (hasCurrentNode && !isActive) {
        const textW = ctx.measureText(label).width;
        ctx.beginPath();
        ctx.arc(x + tabW / 2 + textW / 2 + 6, TAB_HEIGHT / 2, 3, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.nodeCurrent;
        ctx.fill();
      }
    });
  }

  private drawConnections(
    ctx: CanvasRenderingContext2D,
    floor: MapFloor,
    w: number, h: number, offsetY: number,
  ): void {
    floor.nodes.forEach((node) => {
      if (!this.isNodeVisible(node)) return;
      const pos = this.nodeScreen(node, floor, w, h, offsetY);
      node.neighbors.forEach((nId) => {
        const neighbor = floor.nodes.find((n) => n.id === nId);
        if (!neighbor || !this.isNodeVisible(neighbor)) return;
        const nPos = this.nodeScreen(neighbor, floor, w, h, offsetY);

        ctx.beginPath();
        ctx.moveTo(pos.x, pos.y);
        ctx.lineTo(nPos.x, nPos.y);
        ctx.strokeStyle = COLORS.connection;
        ctx.lineWidth = 1.5;
        ctx.setLineDash([]);
        ctx.stroke();
      });

      // Exit links (dashed)
      if (node.exitTo) {
        const pos2 = this.nodeScreen(node, floor, w, h, offsetY);
        ctx.beginPath();
        ctx.arc(pos2.x, pos2.y, NODE_RADIUS + 5, 0, Math.PI * 2);
        ctx.strokeStyle = COLORS.connectionExit;
        ctx.lineWidth = 1.5;
        ctx.setLineDash([3, 3]);
        ctx.stroke();
        ctx.setLineDash([]);
      }
    });
  }

  private drawNodes(
    ctx: CanvasRenderingContext2D,
    floor: MapFloor,
    w: number, h: number, offsetY: number,
  ): void {
    floor.nodes.forEach((node) => {
      if (!this.isNodeVisible(node)) return;
      const pos = this.nodeScreen(node, floor, w, h, offsetY);
      const isCurrent = node.id === this.currentNodeId;
      const isHovered = node.id === this.hoveredNodeId;
      const r = isCurrent ? NODE_RADIUS_CURRENT : (isHovered ? NODE_RADIUS + 1 : NODE_RADIUS);

      // Glow for current
      if (isCurrent) {
        ctx.save();
        ctx.shadowColor = COLORS.nodeCurrent;
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.arc(pos.x, pos.y, r, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.nodeCurrent;
        ctx.fill();
        ctx.restore();
      }

      ctx.beginPath();
      ctx.arc(pos.x, pos.y, r, 0, Math.PI * 2);
      ctx.fillStyle = isCurrent ? COLORS.nodeCurrent : (isHovered ? COLORS.nodeHover : COLORS.node);
      ctx.fill();

      if (isCurrent) {
        ctx.strokeStyle = COLORS.nodeCurrentBorder;
        ctx.lineWidth = 2.5;
        ctx.stroke();
      } else if (isHovered) {
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }
    });
  }

  private drawCameraArrow(
    ctx: CanvasRenderingContext2D,
    floor: MapFloor,
    w: number, h: number, offsetY: number,
  ): void {
    const curNode = floor.nodes.find((n) => n.id === this.currentNodeId);
    if (!curNode) return;
    const pos = this.nodeScreen(curNode, floor, w, h, offsetY);

    // Three camera positive yaw is counter-clockwise on a north-up map.
    const angle = -this.heading.yaw;
    const tipX = pos.x + Math.sin(angle) * ARROW_LENGTH;
    const tipY = pos.y - Math.cos(angle) * ARROW_LENGTH;

    ctx.save();
    ctx.translate(tipX, tipY);
    ctx.rotate(angle);
    ctx.beginPath();
    ctx.moveTo(0, -7);
    ctx.lineTo(-5, 4);
    ctx.lineTo(5, 4);
    ctx.closePath();
    ctx.fillStyle = COLORS.arrow;
    ctx.fill();
    ctx.restore();
  }

  private drawTooltip(
    ctx: CanvasRenderingContext2D,
    floor: MapFloor,
    w: number, h: number, offsetY: number,
  ): void {
    const node = floor.nodes.find((n) => n.id === this.hoveredNodeId);
    if (!node) return;
    const pos = this.nodeScreen(node, floor, w, h, offsetY);

    ctx.font = TOOLTIP_FONT;
    const text = node.name;
    const textW = ctx.measureText(text).width;
    const padX = 8;
    const padY = 5;
    const tipW = textW + padX * 2;
    const tipH = 22;
    let tx = pos.x - tipW / 2;
    let ty = pos.y - NODE_RADIUS_CURRENT - tipH - 6;

    // Clamp to canvas
    tx = Math.max(4, Math.min(w - tipW - 4, tx));
    if (ty < offsetY + 4) ty = pos.y + NODE_RADIUS_CURRENT + 6;

    // Background
    ctx.fillStyle = COLORS.tooltipBg;
    ctx.strokeStyle = COLORS.tooltipBorder;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(tx, ty, tipW, tipH, 5);
    ctx.fill();
    ctx.stroke();

    // Text
    ctx.fillStyle = COLORS.tooltipText;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, tx + tipW / 2, ty + tipH / 2);
  }

  private drawGridPattern(
    ctx: CanvasRenderingContext2D,
    w: number, h: number, offsetY: number,
  ): void {
    const spacing = 24;

    // Subtle grid lines
    ctx.strokeStyle = 'rgba(255,255,255,0.04)';
    ctx.lineWidth = 0.5;
    for (let x = spacing; x < w; x += spacing) {
      ctx.beginPath();
      ctx.moveTo(x, offsetY);
      ctx.lineTo(x, offsetY + h);
      ctx.stroke();
    }
    for (let y = offsetY + spacing; y < offsetY + h; y += spacing) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }

    // Dot grid overlay
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    for (let x = spacing; x < w; x += spacing) {
      for (let y = offsetY + spacing; y < offsetY + h; y += spacing) {
        ctx.beginPath();
        ctx.arc(x, y, 1, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // Subtle border around map area
    ctx.strokeStyle = 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 1;
    ctx.strokeRect(8, offsetY + 4, w - 16, h - 8);
  }

  // ── Coordinate helpers ────────────────────────────────────────

  private nodeScreen(
    node: MapNode,
    floor: MapFloor,
    w: number, h: number, offsetY: number,
  ): { x: number; y: number } {
    const rect = this.contentRect(floor, w, h, offsetY, this.images.get(floor.id));
    return {
      x: rect.x + (node.x / floor.imageWidth) * rect.width,
      y: rect.y + (node.y / floor.imageHeight) * rect.height,
    };
  }

  private contentRect(
    floor: MapFloor,
    w: number,
    h: number,
    offsetY: number,
    image?: HTMLImageElement,
  ): { x: number; y: number; width: number; height: number } {
    const padding = 12;
    const availableW = Math.max(1, w - padding * 2);
    const availableH = Math.max(1, h - padding * 2);
    const sourceW = image?.naturalWidth || floor.imageWidth || 1;
    const sourceH = image?.naturalHeight || floor.imageHeight || 1;
    const scale = Math.min(availableW / sourceW, availableH / sourceH);
    const width = sourceW * scale;
    const height = sourceH * scale;
    return { x: (w - width) / 2, y: offsetY + (h - height) / 2, width, height };
  }

  private currentFloor(): MapFloor | undefined {
    return this.config.floors.find((f) => f.id === this.currentFloorId);
  }

  private findFloorForNode(nodeId: string): MapFloor | undefined {
    return this.config.floors.find((f) => f.nodes.some((n) => n.id === nodeId));
  }

  private isNodeVisible(node: MapNode): boolean {
    return node.visible === true || node.id === this.currentNodeId;
  }

  // ── Hit testing ───────────────────────────────────────────────

  private hitTestNode(mx: number, my: number): MapNode | null {
    const floor = this.currentFloor();
    if (!floor) return null;
    const showTabs = this.config.showFloorTabs !== false && this.config.floors.length > 1;
    const tabH = showTabs ? TAB_HEIGHT : 0;
    const mapH = this.displayH - tabH;

    let closest: MapNode | null = null;
    let minDist = 18;
    for (const node of floor.nodes) {
      if (!this.isNodeVisible(node)) continue;
      const pos = this.nodeScreen(node, floor, this.displayW, mapH, tabH);
      const dist = Math.hypot(mx - pos.x, my - pos.y);
      if (dist < minDist) {
        minDist = dist;
        closest = node;
      }
    }
    return closest;
  }

  private hitTestTab(mx: number, my: number): MapFloor | null {
    const showTabs = this.config.showFloorTabs !== false && this.config.floors.length > 1;
    if (!showTabs || my > TAB_HEIGHT) return null;
    const tabW = this.displayW / this.config.floors.length;
    const index = Math.floor(mx / tabW);
    return this.config.floors[index] ?? null;
  }

  // ── Event handlers ────────────────────────────────────────────

  private handleClick = (e: MouseEvent): void => {
    const { x, y } = this.canvasCoords(e);

    // Tab click
    const tab = this.hitTestTab(x, y);
    if (tab) {
      this.currentFloorId = tab.id;
      this.onFloorChange?.(tab.id);
      this.draw();
      return;
    }

    // Node click
    const node = this.hitTestNode(x, y);
    if (node) this.onNodeClick?.(node.id);
  };

  private handleMouseMove = (e: MouseEvent): void => {
    const { x, y } = this.canvasCoords(e);
    const node = this.hitTestNode(x, y);
    const tab = this.hitTestTab(x, y);
    const newHovered = node?.id ?? null;

    if (newHovered !== this.hoveredNodeId) {
      this.hoveredNodeId = newHovered;
      this.draw();
    }

    this.canvas.style.cursor = (node || tab) ? 'pointer' : 'default';
  };

  private handleMouseLeave = (): void => {
    if (this.hoveredNodeId) {
      this.hoveredNodeId = null;
      this.draw();
    }
    this.canvas.style.cursor = 'default';
  };

  private canvasCoords(e: MouseEvent): { x: number; y: number } {
    const rect = this.canvas.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  }

  // ── Image loading ─────────────────────────────────────────────

  private async loadImage(key: string, url: string): Promise<void> {
    if (!url) return;
    return new Promise<void>((resolve) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => { this.images.set(key, img); resolve(); };
      img.onerror = () => resolve(); // graceful
      img.src = url;
    });
  }
}
import type { Camera } from 'three';
import type { Map as LeafletMap, Marker } from 'leaflet';
import type { IMapStrategy, MapConfig, MapNode } from './IMapStrategy';

/** Real-world viewer map. Leaflet is imported lazily to remain SSR-safe. */
export class LeafletMapStrategy implements IMapStrategy {
  private map: LeafletMap | null = null;
  private leaflet: typeof import('leaflet') | null = null;
  private markers = new Map<string, Marker>();
  private nodes = new Map<string, MapNode>();
  private currentNodeId: string | null = null;
  private headingYaw = 0;
  private container: HTMLElement | null = null;
  onNodeClick?: (nodeId: string) => void;
  onFloorChange?: (floorId: string) => void;

  async init(config: MapConfig, container: HTMLElement): Promise<void> {
    this.container = container;
    this.leaflet = await import('leaflet');
    const geoNodes = config.floors.flatMap(floor => floor.nodes)
      .filter(node => Number.isFinite(node.latitude) && Number.isFinite(node.longitude));
    geoNodes.forEach(node => this.nodes.set(node.id, node));
    const center: [number, number] = geoNodes.length ? [geoNodes[0].latitude!, geoNodes[0].longitude!] : [16.0544, 108.2022];
    this.map = this.leaflet.map(container, { center, zoom: 18, minZoom: 3, maxZoom: 22, zoomControl: true });

    const satellite = this.leaflet.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
      attribution: 'Imagery &copy; Esri', maxNativeZoom: 19, maxZoom: 22,
    }).addTo(this.map);
    const streets = this.leaflet.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; OpenStreetMap', maxNativeZoom: 19, maxZoom: 22,
    });
    const labels = this.leaflet.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}', {
      attribution: '&copy; Esri', maxNativeZoom: 19, maxZoom: 22,
    }).addTo(this.map);
    this.leaflet.control.layers({ 'Vệ tinh': satellite, 'Đường phố': streets }, { 'Tên địa điểm': labels }, { position: 'topright' }).addTo(this.map);

    const bounds: [number, number][] = [];
    for (const node of geoNodes) {
      const point: [number, number] = [node.latitude!, node.longitude!];
      if (node.visible === true) bounds.push(point);
      const marker = this.leaflet.marker(point, { icon: this.makeIcon(node.id) }).addTo(this.map);
      marker.bindTooltip(node.name, { direction: 'top', offset: [0, -15] });
      marker.on('click', () => this.onNodeClick?.(node.id));
      this.markers.set(node.id, marker);
    }
    this.refreshIcons();
    if (bounds.length > 1) this.map.fitBounds(bounds, { padding: [35, 35], maxZoom: 20 });
    requestAnimationFrame(() => this.map?.invalidateSize());
  }

  update(_dt: number, _camera?: Camera): void {}
  setCurrentNode(nodeId: string): void {
    this.currentNodeId = nodeId;
    this.refreshIcons();
    const node = this.nodes.get(nodeId);
    if (node && this.map) this.map.panTo([node.latitude!, node.longitude!], { animate: true });
  }
  setCameraHeading(yaw: number, _pitch: number, _fov?: number): void {
    // Three.js camera convention in this viewer:
    //   yaw = 0 looks toward -Z (map north)
    //   positive yaw turns toward -X (counter-clockwise on a north-up map)
    // CSS rotate() uses the opposite sign (positive = clockwise), therefore
    // negate yaw at this rendering boundary so the map arrow follows camera.
    this.headingYaw = -yaw;
    if (this.currentNodeId) this.markers.get(this.currentNodeId)?.setIcon(this.makeIcon(this.currentNodeId));
  }
  setFloor(_floorId: string): void {}
  setVisible(visible: boolean): void {
    if (this.container) this.container.style.display = visible ? 'block' : 'none';
    if (visible) requestAnimationFrame(() => this.map?.invalidateSize());
  }
  resize(_width: number, _height: number): void { this.map?.invalidateSize(); }
  dispose(): void {
    this.markers.clear(); this.nodes.clear(); this.map?.remove();
    this.map = null; this.leaflet = null; this.container = null;
  }
  private refreshIcons(): void {
    for (const [id, marker] of this.markers) {
      marker.setIcon(this.makeIcon(id));
      const shown = id === this.currentNodeId || this.nodes.get(id)?.visible === true;
      marker.setOpacity(shown ? 1 : 0);
      const element = marker.getElement();
      if (element) element.style.pointerEvents = shown ? 'auto' : 'none';
    }
  }
  private makeIcon(nodeId: string) {
    if (!this.leaflet) throw new Error('Leaflet chưa được khởi tạo.');
    const active = nodeId === this.currentNodeId;
    const arrow = active ? `<span class="v360-map-heading" style="transform:translateX(-50%) rotate(${this.headingYaw}rad)"></span>` : '';
    return this.leaflet.divIcon({
      className: 'v360-map-marker-wrap',
      html: `<span class="v360-map-dot${active ? ' is-active' : ''}"></span>${arrow}`,
      iconSize: active ? [34, 42] : [24, 24], iconAnchor: active ? [17, 21] : [12, 12],
    });
  }
}
/**
 * ─────────────────────────────────────────────────────────────────
 * MapStrategyFactory — Creates the correct IMapStrategy
 *
 * Currently only Map2DStrategy is implemented.
 * Future: MapRealStrategy (Leaflet), Map3DStrategy, etc.
 * ─────────────────────────────────────────────────────────────────
 */

import type { IMapStrategy } from './IMapStrategy';
import { Map2DStrategy } from './Map2DStrategy';
import { LeafletMapStrategy } from './LeafletMapStrategy';
import type { MapConfig } from './IMapStrategy';

export class MapStrategyFactory {
  static create(config?: MapConfig): IMapStrategy {
    const hasGeoNodes = config?.floors.some(floor => floor.nodes.some(node => Number.isFinite(node.latitude) && Number.isFinite(node.longitude)));
    const hasFloorplan = config?.floors.some(floor => Boolean(floor.imageUrl?.trim()));
    // With no floorplan image, Map2DStrategy can only draw its dark fallback
    // background. Prefer the real map even before pins are configured.
    if (config?.mode === 'real' || (config?.mode !== 'floorplan' && (hasGeoNodes || !hasFloorplan))) {
      return new LeafletMapStrategy();
    }
    return new Map2DStrategy();
  }
}
/**
 * ─────────────────────────────────────────────────────────────────
 * MapMarker — extends PanelMarker
 *
 * Renders an interactive map overlay panel in a corner of the viewer.
 * Delegates rendering to IMapStrategy (2D / real / 3D).
 *
 * Because it extends PanelMarker, MarkerPlugin automatically:
 *  - calls updatePanels() every frame
 *  - includes it in panelMarkerTypes()
 *  - closes it on scene transition via hideAllPanels()
 * ─────────────────────────────────────────────────────────────────
 */

import * as THREE from 'three';
import { PanelMarker } from './PanelMarker';
import { MapStrategyFactory } from '../../map/MapStrategyFactory';
import type { IMapStrategy, MapConfig } from '../../map/IMapStrategy';
import type { TourMarker, MapMarkerData } from '~/types/tour';

/**
 * MapMarker — panel-based marker that displays a map overlay.
 *
 * Unlike other PanelMarker subclasses, MapMarker does NOT anchor to a
 * 3D world-space position. Instead it renders a fixed-position panel
 * in a corner of the viewer container.
 */
export class MapMarker extends PanelMarker {
  // @ts-expect-error — narrowing literal type from parent's 'panel'
  override readonly markerType = 'map' as const;
  protected override readonly style = { color: '#2563eb', icon: '🗺', label: 'Bản đồ' };

  private strategy: IMapStrategy | null = null;
  private panelEl: HTMLElement | null = null;
  private mapContainer: HTMLElement | null = null;
  private heading = { yaw: 0, pitch: 0, fov: 75 };
  private _currentNodeId: string | null = null;
  private _visible = true;
  private lifecycle = 0;
  private ready = false;

  // ── Type guard ───────────────────────────────────────────────

  override supports(marker: TourMarker): marker is MapMarkerData {
    return marker.plugin === 'map';
  }

  // ── Sprite anchor ───────────────────────────────────────────

  override createObject(marker: MapMarkerData): THREE.Object3D {
    // Map doesn't appear as a 3D sprite — create a minimal invisible anchor.
    // The actual map UI is a DOM overlay managed separately.
    const sprite = super.createObject(marker);
    // Make the sprite invisible — map is shown via DOM overlay.
    if (sprite instanceof THREE.Sprite) {
      sprite.material.opacity = 0;
      sprite.material.depthTest = false;
      sprite.visible = false;
    }
    return sprite;
  }

  // ── Panel lifecycle ─────────────────────────────────────────

  /**
   * Open or close the map panel. Called from MapPlugin, not from
   * the regular marker-click flow.
   */
  async openMapPanel(
    marker: MapMarkerData,
    container: HTMLElement,
  ): Promise<boolean> {
    if (this.panelEl && this.ready) {
      // Already open — just ensure visible
      this.panelEl.style.display = this._visible ? 'block' : 'none';
      this.strategy?.setVisible(this._visible);
      return true;
    }

    const lifecycle = ++this.lifecycle;
    this.ready = false;

    // Create fixed-position panel
    this.panelEl = document.createElement('div');
    this.panelEl.className = 'view360-map-panel';
    this.panelEl.style.cssText = [
      'position:absolute',
      'z-index:50',
      'pointer-events:auto',
      'border-radius:12px',
      'overflow:hidden',
      'box-shadow:0 8px 32px rgba(0,0,0,0.35)',
      'border:1px solid rgba(255,255,255,0.12)',
      'backdrop-filter:blur(8px)',
      'background:rgba(10,10,20,0.85)',
      'transition:opacity .2s ease',
      this.positionCSS(marker.config.position ?? 'bottom-left'),
      `width:${marker.config.width ?? 300}px`,
      `height:${marker.config.height ?? 220}px`,
    ].join(';');

    if (!document.getElementById('view360-leaflet-map-style')) {
      const style = document.createElement('style');
      style.id = 'view360-leaflet-map-style';
      style.textContent = `
        .view360-map-panel .leaflet-control-layers{font:11px "Be Vietnam Pro",sans-serif;border:0;border-radius:8px;box-shadow:0 3px 14px rgba(0,0,0,.28)}
        .view360-map-panel .leaflet-control-attribution{font-size:8px;background:rgba(255,255,255,.78)}
        .v360-map-marker-wrap{background:none!important;border:0!important}
        .v360-map-dot{position:absolute;left:50%;top:50%;width:16px;height:16px;transform:translate(-50%,-50%);border:3px solid #fff;border-radius:50%;background:#3b82f6;box-shadow:0 2px 8px rgba(0,0,0,.55)}
        .v360-map-dot.is-active{width:22px;height:22px;background:#f59e0b;box-shadow:0 0 0 4px rgba(245,158,11,.28),0 2px 9px rgba(0,0,0,.55)}
        .v360-map-heading{position:absolute;left:50%;top:-9px;width:0;height:0;transform-origin:50% 30px;border-left:7px solid transparent;border-right:7px solid transparent;border-bottom:15px solid #f59e0b;filter:drop-shadow(0 1px 2px rgba(0,0,0,.65))}
      `;
      document.head.appendChild(style);
    }

    // Prevent panorama drag when interacting with map
    ['pointerdown', 'pointerup', 'click', 'wheel', 'touchstart', 'touchend'].forEach((name) => {
      this.panelEl!.addEventListener(name, (e) => e.stopPropagation());
    });

    this.mapContainer = document.createElement('div');
    this.mapContainer.style.cssText = 'width:100%;height:100%';
    this.panelEl.appendChild(this.mapContainer);

    const loadingEl = document.createElement('div');
    loadingEl.textContent = 'Đang tải bản đồ…';
    loadingEl.style.cssText = 'position:absolute;inset:0;display:grid;place-items:center;color:rgba(255,255,255,.7);font:500 12px "Be Vietnam Pro",sans-serif;pointer-events:none';
    this.panelEl.appendChild(loadingEl);
    container.appendChild(this.panelEl);

    // Initialize strategy
    const panelEl = this.panelEl;
    const mapContainer = this.mapContainer;
    const strategy = MapStrategyFactory.create(marker.config);
    this.strategy = strategy;
    strategy.onNodeClick = (nodeId: string) => {
      document.dispatchEvent(
        new CustomEvent('map:node:click', {
          detail: { markerId: marker.id, nodeId },
          bubbles: true,
        }),
      );
    };

    await strategy.init(marker.config, mapContainer);

    // Scene changes can dispose the panel while Leaflet's dynamic import or
    // tile strategy is still initializing. Never let that obsolete task mark
    // the newly active map as ready.
    if (lifecycle !== this.lifecycle || this.panelEl !== panelEl) {
      strategy.dispose();
      panelEl.remove();
      return false;
    }

    loadingEl.remove();
    this.ready = true;
    if (this._currentNodeId) strategy.setCurrentNode(this._currentNodeId);
    strategy.setCameraHeading(this.heading.yaw, this.heading.pitch, this.heading.fov);

    if (!this._visible) this.panelEl.style.display = 'none';
    else strategy.setVisible(true);
    return true;
  }

  // ── Sync methods (called by MapPlugin) ──────────────────────

  syncCameraHeading(yaw: number, pitch: number, fov?: number): void {
    this.heading = { yaw, pitch, fov: fov ?? 75 };
    this.strategy?.setCameraHeading(yaw, pitch, fov);
  }

  syncCurrentNode(nodeId: string): void {
    this._currentNodeId = nodeId;
    this.strategy?.setCurrentNode(nodeId);
  }

  setMapVisible(visible: boolean): void {
    this._visible = visible;
    if (this.panelEl) this.panelEl.style.display = visible ? 'block' : 'none';
    this.strategy?.setVisible(visible);
  }

  isMapVisible(): boolean {
    return this._visible;
  }

  /**
   * Switch strategy at runtime. Disposes old, creates new.
   */
  async switchMode(marker: MapMarkerData, newConfig: MapConfig): Promise<void> {
    this.strategy?.dispose();
    this.strategy = null;
    if (this.mapContainer) this.mapContainer.innerHTML = '';

    this.strategy = MapStrategyFactory.create(newConfig);
    this.strategy.onNodeClick = (nodeId: string) => {
      document.dispatchEvent(
        new CustomEvent('map:node:click', {
          detail: { markerId: marker.id, nodeId },
          bubbles: true,
        }),
      );
    };

    if (this.mapContainer) {
      await this.strategy.init(newConfig, this.mapContainer);
      if (this._currentNodeId) this.strategy.setCurrentNode(this._currentNodeId);
      this.strategy.setCameraHeading(this.heading.yaw, this.heading.pitch, this.heading.fov);
    }
  }

  // ── Dispose ─────────────────────────────────────────────────

  override disposeObject(object: THREE.Object3D): void {
    super.disposeObject(object);
    this.disposeMap();
  }

  disposeMap(): void {
    this.lifecycle++;
    this.ready = false;
    this.strategy?.dispose();
    this.strategy = null;
    this.panelEl?.remove();
    this.panelEl = null;
    this.mapContainer = null;
  }

  // ── Helpers ─────────────────────────────────────────────────

  private positionCSS(pos: string): string {
    switch (pos) {
      case 'top-left':     return 'top:16px;left:16px';
      case 'top-right':    return 'top:16px;right:16px';
      case 'bottom-left':  return 'bottom:16px;left:16px';
      case 'bottom-right': return 'bottom:16px;right:16px';
      default:             return 'bottom:16px;left:16px';
    }
  }
}
/**
 * ─────────────────────────────────────────────────────────────────
 * MapPlugin — extends MarkerPlugin
 *
 * Adds a multi-floor map overlay to the 360° viewer.
 * Inherits ALL of MarkerPlugin's infrastructure (CSS3D, raycasting,
 * panels, drag, fade, hover) and adds:
 *   - MapMarker type registration
 *   - Camera heading → map sync
 *   - Current node → map sync (auto floor switching)
 *   - Top-level TourConfig.map support (auto-inject)
 *   - switchMode() / setVisible() / updateConfig() APIs
 * ─────────────────────────────────────────────────────────────────
 */

import { MarkerPlugin, type MarkerPluginOptions } from './MarkerPlugin';
import { MapMarker } from './markers/MapMarker';
import type { MapConfig } from '../map/IMapStrategy';
import type { TourScene, TourMarker, MapMarkerData } from '~/types/tour';

export interface MapPluginOptions extends MarkerPluginOptions {
  /** Default map config — auto-injected into every scene if no map marker exists. */
  defaultConfig?: MapConfig;
}

/**
 * MapPlugin — extends MarkerPlugin.
 *
 * Usage:
 * ```ts
 * engine.addPlugin(new MapPlugin({ defaultConfig: tourConfig.map }));
 * ```
 */
export class MapPlugin extends MarkerPlugin {
  override readonly id: string = 'map';
  override readonly name: string = 'Map Plugin';

  private readonly mapMarker: MapMarker;
  private readonly defaultConfig?: MapConfig;
  private currentYaw = 0;
  private currentPitch = 0;
  private currentFov = 75;
  private currentSceneId: string | null = null;
  /** Only mapped scenes are allowed to move the active pin/heading. */
  private currentSceneIsMapped = false;
  /** Map belonging to the active scene, even when its DOM panel is hidden. */
  private currentMapData: MapMarkerData | null = null;
  private mapOpenTask: Promise<void> | null = null;

  constructor(options: MapPluginOptions = {}) {
    super(options);

    this.defaultConfig = options.defaultConfig;
    this.mapMarker = new MapMarker();
    // The map is optional viewer UI. Keep it hidden until the visitor
    // explicitly opens it, unless a tour deliberately opts into visibility.
    this.mapMarker.setMapVisible(options.defaultConfig?.visible === true);

    // Register the 'map' marker type so MarkerPlugin recognizes it.
    this.registerMarkerType(this.mapMarker);
  }

  // ── Lifecycle overrides ─────────────────────────────────────

  protected override onInit(): void {
    super.onInit();

    // Sync camera heading to map every frame via the bus
    this.unsubs.push(
      this.ctx.bus.on('camera:move', ({ yaw, pitch }) => {
        this.currentYaw = yaw;
        this.currentPitch = pitch;
        if (this.currentSceneIsMapped) {
          this.mapMarker.syncCameraHeading(yaw, pitch, this.currentFov);
        }
      }),

      this.ctx.bus.on('camera:fov', ({ fov }) => {
        this.currentFov = fov;
        if (this.currentSceneIsMapped) {
          this.mapMarker.syncCameraHeading(this.currentYaw, this.currentPitch, fov);
        }
      }),
    );

    // Listen for map node clicks dispatched as DOM CustomEvents
    const handleNodeClick = (e: Event) => {
      const { nodeId, markerId } = (e as CustomEvent).detail;
      this.ctx.bus.emit('map:node:click', { markerId, nodeId });
      if (this.defaultConfig?.clickToNavigate !== false) {
        this.ctx.bus.emit('navigate', { sceneId: nodeId });
      }
    };
    document.addEventListener('map:node:click', handleNodeClick);
    this.unsubs.push(() => document.removeEventListener('map:node:click', handleNodeClick));

    this.ctx.bus.emit('map:ready', {});
  }

  protected override onUpdate(delta: number): void {
    super.onUpdate(delta);
    // Strategy.update() is handled internally by MapMarker via
    // PanelMarker.updatePanels() which MarkerPlugin already calls.
  }

  protected override onDestroy(): void {
    this.mapMarker.disposeMap();
    super.onDestroy();
    this.ctx.bus.emit('map:destroyed');
  }

  override onSceneLoad(scene: TourScene): void {
    // Don't hide the map panel during transitions — it should persist.
    // But let base class fade out the 3D sprite markers.
    super.onSceneLoad(scene);
  }

  override onSceneReady(scene: TourScene): void {
    super.onSceneReady(scene);
    this.currentSceneId = scene.id;
    this.currentYaw = this.ctx.camera.getYaw();
    this.currentPitch = this.ctx.camera.getPitch();
    this.currentFov = this.ctx.camera.getFov();

    const explicitMap = scene.markers?.find(
      (marker): marker is MapMarkerData => marker.plugin === 'map',
    );

    // Keep the active config independently from the Three.js object. The base
    // plugin disposes marker objects on every scene change, including the map
    // panel, so the viewer must be able to recreate that panel afterwards.
    this.currentMapData = explicitMap ?? this.createDefaultMapData();
    this.currentSceneIsMapped = this.isSceneShownOnMap(scene.id);

    if (this.currentMapData && !explicitMap) {
      this.addMarkerObject(this.mapMarker.createObject(this.currentMapData));
    }

    // Recreate the panel after a scene transition when it was open before.
    if (this.mapMarker.isMapVisible()) void this.ensureMapPanel();

    // A scene may exist in the tour without being a public map point. In that
    // case preserve the last mapped position instead of moving/creating a pin.
    if (this.currentSceneIsMapped) {
      this.mapMarker.syncCurrentNode(scene.id);
      this.mapMarker.syncCameraHeading(this.currentYaw, this.currentPitch, this.currentFov);
    }
  }

  // ── Public API ──────────────────────────────────────────────

  /** Toggle map visibility. */
  setVisible(visible: boolean): void {
    this.mapMarker.setMapVisible(visible);
    if (visible) void this.ensureMapPanel();
    this.ctx.bus.emit('map:visibility', { visible });
  }

  /** Get current visibility state. */
  isVisible(): boolean {
    return this.mapMarker.isMapVisible();
  }

  /** Switch map strategy at runtime. */
  async switchMode(newConfig: MapConfig): Promise<void> {
    const markerData = this.getMapMarkerData();
    if (!markerData) {
      console.warn('[MapPlugin] No map marker found to switch mode.');
      return;
    }
    Object.assign(markerData.config, newConfig);
    await this.mapMarker.switchMode(markerData, newConfig);
    this.ctx.bus.emit('map:config:updated', { config: newConfig });
  }

  /** Update config without changing strategy. */
  updateConfig(partial: Partial<MapConfig>): void {
    const markerData = this.getMapMarkerData();
    if (!markerData) return;
    Object.assign(markerData.config, partial);
    this.ctx.bus.emit('map:config:updated', { config: markerData.config });
  }

  /** Get current map config (for Vue bindings). */
  getConfig(): MapConfig | undefined {
    return this.getMapMarkerData()?.config;
  }

  // ── Private helpers ─────────────────────────────────────────

  private hasMapMarker(scene: TourScene): boolean {
    return !!scene.markers?.some((m) => m.plugin === 'map');
  }

  private getMapMarkerData(): MapMarkerData | undefined {
    if (this.currentMapData) return this.currentMapData;
    for (const child of this.group.children) {
      const marker = child.userData.marker as TourMarker | undefined;
      if (marker?.plugin === 'map') return marker as MapMarkerData;
    }
    return undefined;
  }

  private isSceneShownOnMap(sceneId: string): boolean {
    return this.currentMapData?.config.floors.some(floor =>
      floor.nodes.some(node => node.id === sceneId && node.visible === true),
    ) === true;
  }

  /**
   * Inject a virtual map marker into the scene and immediately open
   * its panel. The marker is hidden (no 3D sprite) — only the panel
   * overlay is shown.
   */
  private createDefaultMapData(): MapMarkerData | null {
    if (!this.defaultConfig) return null;
    return {
      id: '__map__',
      plugin: 'map',
      label: 'Bản đồ',
      yaw: 0,
      pitch: 0,
      config: { ...this.defaultConfig },
    };
  }

  /** Ensure that toggling the map on also creates its DOM/Leaflet panel. */
  private ensureMapPanel(): Promise<void> {
    if (this.mapOpenTask) return this.mapOpenTask;
    const markerData = this.currentMapData;
    if (!markerData) return Promise.resolve();

    let cancelled = false;
    this.mapOpenTask = this.mapMarker.openMapPanel(markerData, this.ctx.container)
      .then((opened) => {
        cancelled = !opened;
      })
      .catch((error) => {
        // A provider or Leaflet failure must not interrupt panorama rendering,
        // but dispose the partial panel so the next click can retry cleanly.
        console.error('[MapPlugin] Không thể mở bản đồ:', error);
        this.mapMarker.disposeMap();
      })
      .finally(() => {
        this.mapOpenTask = null;
        // A scene transition cancelled an older async initialization. Start
        // once more using the active scene/config instead of leaving a shell.
        if (cancelled && this.mapMarker.isMapVisible()) {
          void this.ensureMapPanel();
        }
      });
    return this.mapOpenTask;
  }
}
/**
 * ─────────────────────────────────────────────────────────────────
 * AutorotatePlugin — Auto-rotation after idle timeout
 *
 * Features:
 *   - Configurable idle delay (default 2 min)
 *   - Speed & direction configurable
 *   - Automatically pauses on drag
 *   - Smooth ramp-up from idle
 * ─────────────────────────────────────────────────────────────────
 */

import { PluginBase } from './PluginBase';

export interface AutorotatePluginOptions {
  speed?: number;        // rad/sec. Default 0.3
  idleDelayMs?: number;  // ms before starting. Default 120000 (2 min)
  direction?: 1 | -1;   // 1 = counterclockwise, -1 = clockwise
}

export class AutorotatePlugin extends PluginBase {
  readonly id = 'autorotate';
  readonly name = 'Autorotate Plugin';

  private speed: number;
  private idleDelayMs: number;
  private direction: 1 | -1;

  private isActive = false;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private rampProgress = 0; // 0–1, ramp-up factor

  private unsubs: Array<() => void> = [];

  constructor(opts: AutorotatePluginOptions = {}) {
    super();
    this.speed = opts.speed ?? 0.3;
    this.idleDelayMs = opts.idleDelayMs ?? 120_000;
    this.direction = opts.direction ?? 1;
  }

  protected override onInit(): void {
    this.scheduleStart();

    // Pause on any drag interaction
    const stopOnDrag = () => {
      this.isActive = false;
      this.rampProgress = 0;
      this.scheduleStart();
    };

    const unsub1 = this.ctx.bus.on('interaction:dragstart', stopOnDrag);
    const unsub2 = this.ctx.bus.on('scene:transition:start', stopOnDrag);

    this.unsubs.push(unsub1, unsub2);
  }

  protected override onUpdate(delta: number): void {
    if (!this.isActive) return;

    // Smooth ramp-up over 2 seconds
    this.rampProgress = Math.min(1, this.rampProgress + delta * 0.5);
    const ease = this.rampProgress * this.rampProgress; // quadratic ease-in

    const yaw = this.ctx.camera.getTargetYaw() + this.direction * this.speed * delta * ease;
    this.ctx.camera.setTarget(yaw, this.ctx.camera.getTargetPitch());
  }

  protected override onDestroy(): void {
    if (this.timer) clearTimeout(this.timer);
    this.unsubs.forEach((fn) => fn());
  }

  private scheduleStart(): void {
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      this.isActive = true;
      this.rampProgress = 0;
    }, this.idleDelayMs);
  }
}
/**
 * ─────────────────────────────────────────────────────────────────
 * useViewerEngine — Bridge Layer cho trang Viewer (người xem)
 *
 * Đây là TOÀN BỘ điểm tiếp xúc giữa Vue và core Three.js engine.
 * - Vue components KHÔNG được import từ core/three/ trực tiếp
 * - Chỉ nhận/trả về các Vue ref và plain objects
 * ─────────────────────────────────────────────────────────────────
 */

import { ref, shallowRef, readonly, onBeforeUnmount } from 'vue';
import type { Ref } from 'vue';
import { View360Engine } from '~/core/three/engine/View360Engine';
import type { EngineDiagnostics } from '~/core/three/engine/View360Engine';
import { MarkerPlugin } from '~/core/three/plugins/MarkerPlugin';
import { MapPlugin } from '~/core/three/plugins/MapPlugin';
import { AutorotatePlugin } from '~/core/three/plugins/AutorotatePlugin';
import { AreaHighlightPlugin } from '~/core/three/plugins/AreaHighlightPlugin';
import type { TourScene, TourMarker, TourConfig } from '~/types/tour';
import type { TransitionStyle } from '~/core/three/engine/PanoSphere';

export type { EngineDiagnostics };
export type QualityMode = 'performance' | 'balanced' | 'quality' | 'native';

// ── Options ────────────────────────────────────────────────────

export interface ViewerEngineOptions {
  /** Called when user clicks a navigation marker */
  onNavigate: (sceneId: string, yaw?: number, pitch?: number) => void;
  /** Called when user clicks a non-navigation marker */
  onMarkerClick?: (marker: TourMarker) => void;
  /** Enable auto-rotate after idle */
  autorotate?: boolean;
  /** Transition style between scenes */
  transition?: TransitionStyle;
  /**
   * Delay (ms) before Little Planet intro auto-starts.
   * During countdown, user can click to skip. Default: 0 (no delay).
   * Set to 5000 to match PSV example behavior.
   */
  introDelay?: number;
}

// ── State exported to UI ────────────────────────────────────────

export interface ViewerState {
  isLoading: Ref<boolean>;
  isTransitioning: Ref<boolean>;
  errorMessage: Ref<string>;
  currentScene: Ref<TourScene | null>;
}

// ── Composable ─────────────────────────────────────────────────

export function useViewerEngine(options: ViewerEngineOptions) {
  // ── Reactive state (read-only to UI) ──
  const isLoading = ref(true);
  const isTransitioning = ref(false);
  const errorMessage = ref('');
  const currentScene = ref<TourScene | null>(null);
  const mapAvailable = ref(false);
  const isMapVisible = ref(false);
  /** True while the intro countdown (delay before auto-start) is running */
  const isInCountdown = ref(false);
  /** Remaining ms in countdown (0–introDelay), updated every 100ms */
  const countdownRemaining = ref(0);

  // Engine instance (shallow = no deep reactivity, just reference)
  const engine = shallowRef<View360Engine | null>(null);

  // Preload cache tracking
  const preloaded = new Set<string>();
  let preloadTimer: ReturnType<typeof setTimeout> | null = null;
  let preloadGeneration = 0;
  let isUserDragging = false;
  let lastUserInteractionAt = 0;

  // ── Init ───────────────────────────────────────────────────────

  async function initEngine(
    container: HTMLElement,
    initialScene: TourScene,
    tour?: TourConfig,
  ): Promise<void> {
    isLoading.value = true;
    errorMessage.value = '';

    try {
      const e = new View360Engine({
        container,
        antialias: false,
        introDelay: options.introDelay ?? 0,
        pano: {
          defaultTransition: tour?.transition ?? options.transition ?? 'crossfade',
          transitionDuration: tour?.transitionDuration ?? 700,
          maxCachedTextures: 2,
        },
      });

      // ── Register plugins ──
      e.use(new MarkerPlugin());
      e.use(new AreaHighlightPlugin());

      // Map plugin — auto-enabled when tour has map config
      if (tour?.map) {
        try {
          const sceneById = new Map(tour.scenes.map(scene => [scene.id, scene]));
          // `tour` comes from useFetch and can be a Vue Proxy. structuredClone
          // throws DataCloneError for proxies and used to abort the whole viewer.
          const viewerMap = JSON.parse(JSON.stringify(tour.map)) as NonNullable<TourConfig['map']>;

          // The real-map editor stores the pin choice on each scene. New tours
          // can therefore legitimately have `floors: []`; build the runtime
          // node collection from the selected scenes instead of falling back
          // to an empty 2D floorplan (which only renders a black canvas).
          if (viewerMap.floors.length === 0) {
            viewerMap.floors.push({
              id: '__geo__',
              name: 'Bản đồ',
              shortName: 'Map',
              imageUrl: '',
              imageWidth: 1,
              imageHeight: 1,
              nodes: [],
            });
          }

          const configuredNodeIds = new Set(
            viewerMap.floors.flatMap(floor => floor.nodes.map(node => node.id)),
          );
          const geoFloor = viewerMap.floors[0]!;
          for (const scene of tour.scenes) {
            if (
              scene.showOnMap === true
              && scene.coordinates
              && !configuredNodeIds.has(scene.id)
            ) {
              geoFloor.nodes.push({
                id: scene.id,
                name: scene.title,
                x: 0,
                y: 0,
                longitude: scene.coordinates[0],
                latitude: scene.coordinates[1],
                visible: true,
                neighbors: [],
              });
              configuredNodeIds.add(scene.id);
            }
          }

          for (const floor of viewerMap.floors) {
            for (const node of floor.nodes) {
              const scene = sceneById.get(node.id);
              const coordinates = scene?.coordinates;
              node.visible = scene?.showOnMap === true;
              if (coordinates) {
                node.longitude = coordinates[0];
                node.latitude = coordinates[1];
              }
            }
          }
          const mapPlugin = new MapPlugin({ defaultConfig: viewerMap });
          e.use(mapPlugin);
          mapAvailable.value = true;
          isMapVisible.value = mapPlugin.isVisible();
        } catch (mapError) {
          // The map is supplemental UI. It must never prevent the panorama
          // engine from starting when its configuration is malformed.
          console.error('[useViewerEngine] Không thể khởi tạo MapPlugin:', mapError);
        }
      }

      if (options.autorotate ?? tour?.autoRotate) {
        e.use(new AutorotatePlugin({ speed: 0.3 }));
      }

      // ── Wire events to callbacks ──
      e.bus.on('navigate', ({ sceneId, yaw, pitch }) => options.onNavigate(sceneId, yaw, pitch));

      e.bus.on('marker:click', ({ marker }) => {
        if (marker.plugin !== 'navigation') {
          options.onMarkerClick?.(marker);
        }
      });

      e.bus.on('scene:transition:start', () => {
        isTransitioning.value = true;
        cancelScheduledPreload();
      });

      e.bus.on('scene:transition:end', ({ scene }) => {
        isTransitioning.value = false;
        currentScene.value = scene;
      });

      e.bus.on('scene:loaded', ({ scene }) => {
        currentScene.value = scene;
        isLoading.value = false;
      });
      e.bus.on('interaction:dragstart', () => {
        isUserDragging = true;
        lastUserInteractionAt = performance.now();
      });
      e.bus.on('interaction:dragend', () => {
        isUserDragging = false;
        lastUserInteractionAt = performance.now();
      });
      e.bus.on('camera:fov', () => {
        lastUserInteractionAt = performance.now();
      });
      e.bus.on('map:visibility', ({ visible }) => {
        isMapVisible.value = visible;
      });

      // ── Intro countdown state ──
      let countdownInterval: ReturnType<typeof setInterval> | null = null;
      e.bus.on('intro:countdown:start', ({ delayMs }) => {
        isInCountdown.value = true;
        countdownRemaining.value = delayMs;
        countdownInterval = setInterval(() => {
          countdownRemaining.value = Math.max(0, countdownRemaining.value - 100);
        }, 100);
      });
      e.bus.on('intro:end', () => {
        isInCountdown.value = false;
        countdownRemaining.value = 0;
        if (countdownInterval) { clearInterval(countdownInterval); countdownInterval = null; }
      });
      e.bus.on('intro:countdown:skip', () => {
        isInCountdown.value = false;
        countdownRemaining.value = 0;
        if (countdownInterval) { clearInterval(countdownInterval); countdownInterval = null; }
      });

      engine.value = e;

      // ── Load first scene ──
      const viewerInitialScene = forViewer(initialScene);
      await e.loadScene(viewerInitialScene, true);

      const viewerScenes = tour?.scenes.map(forViewer);
      if (viewerInitialScene.previewPanorama) {
        scheduleCurrentSceneUpgrade(viewerInitialScene, viewerScenes);
      } else if (viewerScenes) {
        preloadNeighbours(viewerInitialScene, viewerScenes);
      }
    } catch (err) {
      errorMessage.value =
        err instanceof Error ? err.message : 'Không thể khởi động viewer.';
      isLoading.value = false;
    }
  }

  // ── Navigation ─────────────────────────────────────────────────

  async function navigateTo(
    scene: TourScene,
    allScenes?: TourScene[],
    flyYaw?: number,
    flyPitch?: number,
  ): Promise<void> {
    if (!engine.value) return;
    if (currentScene.value?.id === scene.id) return;

    isTransitioning.value = true;
    try {
      const viewerScene = forViewer(scene);
      await engine.value.navigateTo(viewerScene, undefined, flyYaw, flyPitch);
      const viewerScenes = allScenes?.map(forViewer);
      if (viewerScene.previewPanorama) {
        scheduleCurrentSceneUpgrade(viewerScene, viewerScenes);
      } else if (viewerScenes) {
        preloadNeighbours(viewerScene, viewerScenes);
      }
    } catch (err) {
      errorMessage.value =
        err instanceof Error ? err.message : 'Lỗi chuyển cảnh.';
    } finally {
      isTransitioning.value = false;
    }
  }

  // ── Preload ────────────────────────────────────────────────────

  function preloadNeighbours(scene: TourScene, allScenes: TourScene[]): void {
    if (!engine.value) return;

    // Preload navigation targets + adjacent scenes
    const navTargets = (scene.markers ?? [])
      .filter((m) => m.plugin === 'navigation' && 'targetScene' in m)
      .map((m) => allScenes.find((s) => s.id === (m as any).targetScene))
      .filter((s): s is TourScene => !!s);

    const idx = allScenes.findIndex((s) => s.id === scene.id);
    const adjacent = [allScenes[idx - 1], allScenes[idx + 1]].filter(
      (s): s is TourScene => !!s,
    );

    const targets = [...new Set([...navTargets, ...adjacent])].slice(0, 3);
    const pending = targets.filter(target => !preloaded.has(target.previewPanorama ?? target.panorama));
    const generation = ++preloadGeneration;
    lastUserInteractionAt = performance.now();
    scheduleNextPreload(pending, 0, generation);
  }

  function forViewer(scene: TourScene): TourScene {
    if (typeof window === 'undefined') return scene;
    const preferMobile = window.innerWidth <= 900
      || window.matchMedia('(pointer: coarse)').matches;
    return {
      ...scene,
      panorama: preferMobile && scene.mobilePanorama
        ? scene.mobilePanorama
        : scene.panorama,
    };
  }

  /** Upgrade the active 2K preview only after camera input has gone idle. */
  function scheduleCurrentSceneUpgrade(scene: TourScene, allScenes?: TourScene[]): void {
    const generation = ++preloadGeneration;
    lastUserInteractionAt = performance.now();
    const attempt = () => {
      if (generation !== preloadGeneration || !engine.value) return;
      const idleFor = performance.now() - lastUserInteractionAt;
      if (isUserDragging || idleFor < 1200) {
        preloadTimer = setTimeout(attempt, 250);
        return;
      }
      preloadTimer = null;
      void engine.value.upgradeCurrentPanorama(scene.id, scene.panorama).then(() => {
        if (generation !== preloadGeneration) return;
        if (allScenes) preloadNeighbours(scene, allScenes);
      }).catch(() => {});
    };
    preloadTimer = setTimeout(attempt, 250);
  }

  /**
   * Full-resolution panorama decode + GPU upload is expensive. Run only one
   * preload at a time and wait until camera interaction has been idle, rather
   * than uploading three textures on the first frames after a transition.
   */
  function scheduleNextPreload(
    targets: TourScene[],
    index: number,
    generation: number,
  ): void {
    if (generation !== preloadGeneration || index >= targets.length) return;
    if (preloadTimer) clearTimeout(preloadTimer);
    preloadTimer = setTimeout(async () => {
      preloadTimer = null;
      if (generation !== preloadGeneration) return;

      const idleFor = performance.now() - lastUserInteractionAt;
      if (isUserDragging || idleFor < 1200) {
        scheduleNextPreload(targets, index, generation);
        return;
      }

      const target = targets[index];
      const pano = engine.value?.pano;
      if (!target || !pano) return;
      const targetUrl = target.previewPanorama ?? target.panorama;
      preloaded.add(targetUrl);
      try {
        await pano.preload(targetUrl);
      } catch {
        preloaded.delete(targetUrl);
      }
      // Leave breathing room between GPU uploads as well.
      lastUserInteractionAt = performance.now() - 700;
      scheduleNextPreload(targets, index + 1, generation);
    }, 250);
  }

  function cancelScheduledPreload(): void {
    preloadGeneration++;
    if (preloadTimer) {
      clearTimeout(preloadTimer);
      preloadTimer = null;
    }
  }

  // ── Dev Tools ──────────────────────────────────────────────────

  /** Snapshot of GPU/rendering metrics. Only call after engine is initialized. */
  function getDiagnostics(): EngineDiagnostics | null {
    return engine.value?.getDiagnostics() ?? null;
  }

  /**
   * Change renderer quality mode.
   * Takes effect immediately without restarting the engine.
   */
  function setQualityMode(mode: QualityMode): void {
    engine.value?.setQualityMode(mode);
  }

  function toggleMap(): void {
    const plugin = engine.value?.getPlugin<MapPlugin>('map');
    if (!plugin) return;
    plugin.setVisible(!plugin.isVisible());
  }

  // ── Cleanup ────────────────────────────────────────────────────

  function destroyEngine(): void {
    cancelScheduledPreload();
    engine.value?.destroy();
    engine.value = null;
    preloaded.clear();
    currentScene.value = null;
    mapAvailable.value = false;
    isMapVisible.value = false;
  }

  // Auto-cleanup when parent component unmounts
  onBeforeUnmount(destroyEngine);

  // ── Return (read-only state + actions) ────────────────────────

  return {
    // State — readonly so UI cannot mutate directly
    isLoading: readonly(isLoading),
    isTransitioning: readonly(isTransitioning),
    errorMessage: readonly(errorMessage),
    currentScene: readonly(currentScene),
    mapAvailable: readonly(mapAvailable),
    isMapVisible: readonly(isMapVisible),

    // Actions
    initEngine,
    navigateTo,
    destroyEngine,

    // Dev tools
    getDiagnostics,
    setQualityMode,
    toggleMap,
  };
}
<script setup lang="ts">
/**
 * DevDiagnosticPanel — Bảng chẩn đoán GPU/texture
 *
 * CHỈ hiện trong development (process.dev).
 * Toggle bằng phím ` (backtick) hoặc nút.
 *
 * Không cần import thêm gì ngoài Vue + dữ liệu từ getDiagnostics().
 */
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import type { EngineDiagnostics, QualityMode } from '~/composables/viewer/useViewerEngine';

const props = defineProps<{
  getDiagnostics: () => EngineDiagnostics | null;
  setQualityMode: (mode: QualityMode) => void;
  currentQuality: QualityMode;
  panoramaUrl: string;
  embedded?: boolean;
}>();

const emit = defineEmits<{
  qualityChange: [mode: QualityMode];
  compareMode: [mode: 'panorama' | 'flat-100' | 'fit-screen'];
}>();

// ── State ──────────────────────────────────────────────────────
const isOpen   = ref(Boolean(props.embedded));
const diag     = ref<EngineDiagnostics | null>(null);
let   interval: ReturnType<typeof setInterval> | null = null;

const compareMode = ref<'panorama' | 'flat-100' | 'fit-screen'>('panorama');

// ── Auto-refresh diagnostics every 500ms while open ────────────
function refresh() {
  if (!isOpen.value) return;
  diag.value = props.getDiagnostics();
}

function toggle() {
  isOpen.value = !isOpen.value;
  if (isOpen.value) diag.value = props.getDiagnostics();
}

onMounted(() => {
  interval = setInterval(refresh, 500);
  if (!props.embedded) window.addEventListener('keydown', onKey);
  if (props.embedded) diag.value = props.getDiagnostics();
});
onBeforeUnmount(() => {
  if (interval) clearInterval(interval);
  if (!props.embedded) window.removeEventListener('keydown', onKey);
});

function onKey(e: KeyboardEvent) {
  if (['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName)) return;
  if (e.key === '`') toggle();
}

// ── Computed warnings ──────────────────────────────────────────
const warnings = computed<string[]>(() => {
  const d = diag.value;
  if (!d) return [];
  const w: string[] = [];
  if (d.isCapped)           w.push(`⚠ GPU thu ảnh ${d.srcWidth}×${d.srcHeight} xuống ${d.gpuWidth}×${d.gpuHeight} (maxTextureSize: ${d.maxTexSize})`);
  if (d.dpr < 1.5)          w.push(`⚠ DPR thấp (${d.dpr}) — màn hình nét hơn nếu tăng quality`);
  if (d.pixelDensity < 0.9) w.push(`⚠ Pixel density ${d.pixelDensity} — renderer đang upscale (ảnh nguồn không đủ nét)`);
  if (d.pixelDensity > 4)   w.push(`ℹ Pixel density ${d.pixelDensity} — ảnh nguồn thừa chi tiết ở zoom này`);
  if (d.srcWidth < 4096)    w.push(`⚠ Ảnh nguồn ${d.srcWidth}px — khuyến nghị tối thiểu 5760px`);
  return w;
});

const densityLabel = computed(() => {
  const d = diag.value?.pixelDensity ?? 0;
  if (d < 0.9) return { text: 'Upscaling ↓ mờ', cls: 'warn-red' };
  if (d < 1.5) return { text: 'Vừa đủ', cls: 'warn-yellow' };
  return { text: 'Thừa chi tiết ✓', cls: 'ok' };
});

// ── Quality mode ───────────────────────────────────────────────
const QUALITY_MODES: { id: QualityMode; label: string; desc: string }[] = [
  { id: 'performance', label: 'Perf',     desc: 'DPR ≤ 1' },
  { id: 'balanced',   label: 'Balanced',  desc: 'DPR ≤ 1.5' },
  { id: 'quality',    label: 'Quality',   desc: 'DPR ≤ 2' },
  { id: 'native',     label: 'Native',    desc: 'DPR gốc' },
];

function setQuality(mode: QualityMode) {
  props.setQualityMode(mode);
  emit('qualityChange', mode);
}

function setCompare(mode: 'panorama' | 'flat-100' | 'fit-screen') {
  compareMode.value = mode;
  emit('compareMode', mode);
}
</script>

<template>
  <!-- Toggle button (always visible in dev) -->
  <button
    v-if="!embedded"
    id="dev-diag-toggle"
    class="diag-toggle"
    :class="{ 'is-open': isOpen }"
    :title="isOpen ? 'Đóng bảng chẩn đoán (`)' : 'Mở bảng chẩn đoán GPU (`)'"
    @click="toggle"
    aria-label="Toggle diagnostic panel"
  >
    <span aria-hidden="true">🔬</span>
  </button>

  <!-- Panel -->
  <Transition name="diag-slide">
    <div
      v-if="isOpen"
      class="diag-panel"
      :class="{ 'is-embedded': embedded }"
      role="region"
      aria-label="Bảng chẩn đoán GPU"
    >
      <div class="diag-header">
        <span class="diag-title">🔬 GPU Diagnostics</span>
        <span class="diag-env">DEV</span>
      </div>

      <!-- Warnings -->
      <div v-if="warnings.length" class="diag-warnings">
        <p v-for="w in warnings" :key="w" class="warn-item">{{ w }}</p>
      </div>
      <div v-else class="diag-ok">✓ Không có cảnh báo</div>

      <!-- Metrics grid -->
      <div v-if="diag" class="diag-grid">
        <!-- Texture source -->
        <div class="diag-section-title">Ảnh nguồn</div>
        <div class="diag-row">
          <span>Kích thước gốc</span>
          <span :class="diag.srcWidth >= 5760 ? 'ok' : 'warn-yellow'">
            {{ diag.srcWidth }}×{{ diag.srcHeight }}
          </span>
        </div>
        <div class="diag-row">
          <span>GPU max texture</span>
          <span :class="diag.maxTexSize >= 8192 ? 'ok' : 'warn-yellow'">
            {{ diag.maxTexSize }}px
          </span>
        </div>
        <div class="diag-row">
          <span>Kích thước trên GPU</span>
          <span :class="diag.isCapped ? 'warn-red' : 'ok'">
            {{ diag.gpuWidth }}×{{ diag.gpuHeight }}
            {{ diag.isCapped ? '(bị cắt!)' : '' }}
          </span>
        </div>

        <!-- Canvas -->
        <div class="diag-section-title">Canvas / Renderer</div>
        <div class="diag-row">
          <span>Canvas CSS</span>
          <span>{{ diag.canvasCssW }}×{{ diag.canvasCssH }}</span>
        </div>
        <div class="diag-row">
          <span>Framebuffer (GL)</span>
          <span>{{ diag.canvasGlW }}×{{ diag.canvasGlH }}</span>
        </div>
        <div class="diag-row">
          <span>DPR hiện tại</span>
          <span :class="diag.dpr >= 1.5 ? 'ok' : 'warn-yellow'">
            {{ diag.dpr.toFixed(2) }}
          </span>
        </div>
        <div class="diag-row">
          <span>DPR thiết bị</span>
          <span>{{ diag.deviceDpr.toFixed(2) }}</span>
        </div>

        <!-- Quality -->
        <div class="diag-section-title">Chất lượng hình ảnh</div>
        <div class="diag-row">
          <span>FOV</span>
          <span>{{ diag.fov.toFixed(1) }}°</span>
        </div>
        <div class="diag-row">
          <span>Pixel density</span>
          <span :class="densityLabel.cls">
            {{ diag.pixelDensity }} — {{ densityLabel.text }}
          </span>
        </div>

        <!-- GPU info -->
        <div class="diag-section-title">GPU</div>
        <div class="diag-row diag-row--wrap">
          <span>Renderer</span>
          <span class="diag-gpu-name">{{ diag.renderer || '—' }}</span>
        </div>
      </div>

      <div v-else class="diag-empty">Engine chưa sẵn sàng</div>

      <!-- Quality mode selector -->
      <div class="diag-section-title" style="margin-top:10px">Quality Mode</div>
      <div class="quality-row">
        <button
          v-for="q in QUALITY_MODES"
          :key="q.id"
          class="quality-btn"
          :class="{ 'is-active': currentQuality === q.id }"
          :title="q.desc"
          @click="setQuality(q.id)"
        >{{ q.label }}</button>
      </div>

      <!-- Image comparison mode -->
      <div class="diag-section-title" style="margin-top:10px">So sánh ảnh</div>
      <div class="quality-row">
        <button
          class="quality-btn" :class="{ 'is-active': compareMode === 'panorama' }"
          @click="setCompare('panorama')"
